    Visited[start[0]][start[1]] = true;

    for (int[] path : paths) {
        int r = start[0] + path[0];
        int c = start[1] + path[1];

        if (r >= 0 && r < rows && c >= 0 && c < cols && !Visited[r][c]) {
            if (canTravelMazeUtil(new int[]{r, c}, end, paths, rows, cols, Visited)) {
                return true;
            }
        }
    }

    return false;
