public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list representation of the graph
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }

    // Initialize the dp array to store the minimum time to reach each node
    int[] dp = new int[n];
    Arrays.fill(dp, Integer.MAX_VALUE);

    // Perform dynamic programming to find the minimum time
    minTime(dp, adj, hasApple, 0, 0);

    // Return the minimum time to reach node 0 with all apples collected
    return dp[0];
}

private int minTime(int[] dp, List<List<Integer>> adj, boolean[] hasApple, int currentNode, int parent) {
    // Base case: return 0 if the current node is a leaf node
    if (adj.get(currentNode).size() == 1 && adj.get(currentNode).get(0) == parent) {
        return 0;
    }

    // If the current node has an apple, add the time to reach and then return to the parent node
    if (hasApple[currentNode]) {
        dp[currentNode] = 2 + Math.min(minTime(dp, adj, hasApple, adj.get(currentNode).get(0), currentNode), dp[currentNode]);
    }

    // If the current node does not have an apple, check all its children
    for (int child : adj.get(currentNode)) {
        if (child != parent) {
            int time = minTime(dp, adj, hasApple, child, currentNode);
            if (time == Integer.MAX_VALUE) {
                continue;
            }
            dp[currentNode] = Math.min(dp[currentNode], time);
        }
    }

    // Return the minimum time to reach the current node with all apples collected
    return dp[currentNode];
}
