    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    StringBuilder result = new StringBuilder();

    while (!minHeap.isEmpty()) {
        if (minHeap.peek() == result.charAt(result.length() - 1)) {
            while (!minHeap.isEmpty() && minHeap.peek() == result.charAt(result.length() - 1)) {
                minHeap.poll();
            }
        }
        if (maxHeap.peek() == result.charAt(result.length() - 1)) {
            while (!maxHeap.isEmpty() && maxHeap.peek() == result.charAt(result.length() - 1)) {
                maxHeap.poll();
            }
        }
        if (!minHeap.isEmpty() && !maxHeap.isEmpty()) {
            char minChar = minHeap.poll();
