public class ArraySplitSolver {

    public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        if ((totalSum & 1) != 0) {
            return false; // If the total sum is odd, it's impossible to split into two equal averages
        }
        int targetSum = totalSum / 2;

        Map<Integer, Integer> cumulativeSums = new HashMap<>();
        cumulativeSums.put(0, 1); // Ensure the base case for empty sum

        int cumulativeSum = 0;
        for (int num : nums) {
            cumulativeSum += num;
            int complement = targetSum - cumulativeSum;
            if (cumulativeSums.containsKey(complement)) {
                return true;
            }
            cumulativeSums.put(cumulativeSum, cumulativeSums.getOrDefault(cumulativeSum, 0) + 1);
        }
        return false;
    }

    // Test cases to verify the solution correctness
    public static void main(String[] args) {
        ArraySplitSolver solver = new ArraySplitSolver();

        // Test cases
        System.out.println(solver.splitArraySameAverage(new int[]{1, 2, 3, 4, 5, 6, 7, 8})); // Output: true
        System.out.println(solver.splitArraySameAverage(new int[]{3, 1})); // Output: false
    }
