public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;

    if (m == 0 || n == 0) return 0;

    int maxLength = 0;
    int[][] directions = new int[][]{{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
    boolean[][] seen = new boolean[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0 || seen[i][j]) continue;

            int length = 1;
            for (int[] dir : directions) {
                int newX = i + dir[0];
                int newY = j + dir[1];
                while (newX >= 0 && newX < m && newY >= 0 && newY < n && mat[newX][newY] == 1 && !seen[newX][newY]) {
                    length++;
                    seen[newX][newY] = true;
                    newX += dir[0];
                    newY += dir[1];
                }
            }
            maxLength = Math.max(maxLength, length);
        }
    }

    return maxLength;
}
