public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 1) {
        return A[0] % 4 == 0 ? 1 : 0;
    }

    boolean[] visited = new boolean[n];
    int count = 0;
    permute(A, 0, visited, count);
    return count;
