private static void permute(int[] A, int index, boolean[] visited, int count) {
    if (index == A.length) {
        if (isValid(A)) {
            count++;
        }
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            visited[i] = true;
            permute(A, index + 1, visited, count);
            visited[i] = false;
        }
    }
}

private static boolean isValid(int[] A) {
    for (int i = 1; i < A.length; i++) {
        if (!isPerfectSquare(A[i] - A[i - 1])) {
            return false;
        }
    }
    return true;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
