public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Find the nearest smaller value to the left of each element
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack
    stack.clear();

    // Find the nearest smaller value to the right of each element
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = n;
        } else {
            rightSmaller[i] = stack.peek();
        }
        stack.push(i);
    }

    // Calculate the area of each bar as the width times the height
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = width * heights[i];
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}
