    int i = 0, j = 0, k = 0, len = m * n;
    int[] result = new int[len];
    int count = 0;
    boolean directionChanged = false;

    while (count < len) {
        result[count++] = mat[i][j];

        int nextI = i + directions[k][0], nextJ = j + directions[k][1];
        if (nextI < 0 || nextI >= m || nextJ < 0 || nextJ >= n || mat[nextI][nextJ] == 0) {
            if (!directionChanged) {
                k = (k + 1) % 2;
                directionChanged = true;
            }
            nextI = i + directions[k][0], nextJ = j + directions[k][1];
            if (nextI < 0 || nextI >= m || nextJ < 0 || nextJ >= n) {
                break;
            }
        }
        i = nextI;
        j = nextJ;
    }

    return result;
