    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int index2 = 1;
    int index3 = 1;
    int index5 = 1;

    for (int i = 1; i < n; i++) {
        int minNum = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = minNum;

        if (minNum == nextMultipleOf2) {
            index2++;
        }
        if (minNum == nextMultipleOf3) {
            index3++;
        }
        if (minNum == nextMultipleOf5) {
            index5++;
        }

        nextMultipleOf2 *= 2;
        nextMultipleOf3 *= 3;
        nextMultipleOf5 *= 5;
    }

    return uglyNumbers[n - 1];
