public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxLength = 1;
    int currentLength = 1;
    int lastChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            currentLength++;
        } else {
            lastChar = s.charAt(i);
            currentLength = 1;
        }

        maxLength = Math.max(maxLength, currentLength);
    }

    return maxLength;
}
