import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class LexicalOrder {

    public static List<Integer> lexicalOrder(int n) {
        List<Integer> list = new ArrayList<>();
        generateLexicalOrder(1, n, new ArrayList<>(), list);
        Collections.sort(list);
        return list;
    }

    private static void generateLexicalOrder(int start, int end, List<Integer> current, List<Integer> list) {
        if (start > end) {
            return;
        }

        current.add(start);
        list.add(start);

        for (int i = start * 10; i <= end && i < 100; i *= 10) {
            // Recursive call for the next digit
            generateLexicalOrder(i, end, new ArrayList<>(current), list);
            current.remove(current.size() - 1);
        }
    }

    // Test cases to verify the solution correctness
    public static void main(String[] args) {
        List<Integer> result = lexicalOrder(13);
        System.out.println(result); // Output: [1,10,11,12,13,2,3,4,5,6,7,8,9]
    }
}
