public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum number of perfect squares needed
        int srt = (int) Math.sqrt(i);
        for (int j = 1; j <= srt; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}
